-- ------------------------------------------------------------------
-- The moonkin form
-- ------------------------------------------------------------------
-- The script hooks onto the NATIVE moonkin form spell, whose first effect carries
-- SPELL_AURA_MOD_SHAPESHIFT. The generator only names our own spells, so the
-- binding lives here.

DELETE FROM `spell_script_names`
    WHERE `spell_id` = 24858 AND `ScriptName` = 'spell_spheregrid_moonkin_form';
INSERT INTO `spell_script_names` (`spell_id`, `ScriptName`)
VALUES (24858, 'spell_spheregrid_moonkin_form');

-- ------------------------------------------------------------------
-- The gauge auras
-- ------------------------------------------------------------------
-- The gauge auras must never be saved: Aura::CanBeSaved reads this custom
-- attribute, which is loaded at server startup.
-- (2026-09-06).
--
-- SPELL_ATTR0_CU_AURA_CANNOT_BE_SAVED (0x01000000, spell_custom_attr) :
--   8610029 Solstice, 8610030 Equinoxe (bouts atteints, 6 s)
--   8610032 Jauge lunaire, 8610033 Jauge solaire (piles)
--   8610034 Soleil epuise, 8610035 Lune epuisee (verrous)
DELETE FROM `spell_custom_attr` WHERE `spell_id` BETWEEN 8610029 AND 8610035;
INSERT INTO `spell_custom_attr` (`spell_id`, `attributes`) VALUES
(8610029, 0x01000000), (8610030, 0x01000000), (8610031, 0x01000000),
(8610032, 0x01000000), (8610033, 0x01000000), (8610034, 0x01000000),
(8610035, 0x01000000);

